/**
 * Окрема святкова ялинка зі зіркою:
 * Має гармонійний розмір та однакове сяйво з написом
 */
export function BrandTreeIcon({
  animated = true,
  label = "Jingle Decor",
  className = "h-[25px] sm:h-[26px] md:h-[27px] w-auto shrink-0",
  ...props
}: BrandSvgProps) {
  const rawId = useId()
  const cleanId = rawId.replace(/[^a-zA-Z0-9_-]/g, "")
  const maskId = `tree-mask-${cleanId}`
  const shimmerId = `tree-shimmer-${cleanId}`

  return (
    <svg
      viewBox="0 0 89 108"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label={label}
      className={cn(
        "dark:drop-shadow-[0_0_8px_rgba(255,223,133,0.3)] transition-all duration-300",
        className
      )}
      {...props}
    >
      <defs>
        {animated && (
          <>
            <linearGradient id={shimmerId} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#FFFFFF" stopOpacity="0" />
              <stop offset="50%" stopColor="#FFFFFF" stopOpacity="0.85" />
              <stop offset="100%" stopColor="#FFFFFF" stopOpacity="0" />
            </linearGradient>
            <mask id={maskId}>
              <path
                d={STAR_PATH}
                stroke="white"
                strokeWidth="2.4"
                strokeLinejoin="round"
                fill="none"
              />
              <path d={TREE_PATH} fill="white" />
            </mask>
          </>
        )}
      </defs>

      <path
        d={STAR_PATH}
        strokeWidth="2.4"
        strokeLinejoin="round"
        fill="none"
        className="stroke-[#7A4F08] dark:stroke-[#FFDF85] transition-colors duration-300"
      />
      <path
        d={TREE_PATH}
        className="fill-[#7A4F08] dark:fill-[#FFDF85] transition-colors duration-300"
      />

      {animated && (
        <g mask={`url(#${maskId})`} className="pointer-events-none">
          <rect
            className="animate-logo-shimmer"
            x="0"
            y="-10"
            width="45"
            height="130"
            fill={`url(#${shimmerId})`}
          />
        </g>
      )}
    </svg>
  )
}

/**
 * Чіткий, яскравий каліграфічний напис «Jingle DECOR»
 */
export function BrandNameLogo({
  animated = true,
  label = "Jingle Decor",
  className = "h-[30px] sm:h-[32px] md:h-[33px] w-auto shrink-0",
  ...props
}: BrandSvgProps) {
  const rawId = useId()
  const cleanId = rawId.replace(/[^a-zA-Z0-9_-]/g, "")
  const maskId = `name-mask-${cleanId}`
  const shimmerId = `name-shimmer-${cleanId}`
  const sparkleGlowId = `sparkle-glow-${cleanId}`

  return (
    <svg
      viewBox="0 0 348 114"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label={label}
      className={cn(
        "dark:drop-shadow-[0_0_8px_rgba(255,223,133,0.3)] transition-all duration-300",
        className
      )}
      {...props}
    >
      <defs>
        {animated && (
          <>
            <linearGradient id={shimmerId} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#FFF6D6" stopOpacity="0" />
              <stop offset="50%" stopColor="#FFFDF5" stopOpacity="0.98" />
              <stop offset="100%" stopColor="#FFF6D6" stopOpacity="0" />
            </linearGradient>
            <radialGradient id={sparkleGlowId} cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="#FFFDF2" stopOpacity="1" />
              <stop offset="40%" stopColor="#F3D078" stopOpacity="0.7" />
              <stop offset="100%" stopColor="#D4AF37" stopOpacity="0" />
            </radialGradient>
            <mask id={maskId}>
              <path
                d={JINGLE_PATH}
                fill="white"
                stroke="white"
                strokeWidth="0.85"
                strokeLinejoin="round"
              />
              <path
                d={DECOR_PATH}
                fill="white"
                stroke="white"
                strokeWidth="0.5"
                strokeLinejoin="round"
              />
            </mask>
          </>
        )}
      </defs>

      {/* Jingle: чіткі золоті лінії каліграфії */}
      <path
        d={JINGLE_PATH}
        strokeWidth="0.85"
        strokeLinejoin="round"
        className="fill-[#7A4F08] stroke-[#7A4F08] dark:fill-[#FFDF85] dark:stroke-[#FFDF85] transition-colors duration-300"
      />

      {/* DECOR: підкреслена чіткість тонких ліній зарубок */}
      <path
        d={DECOR_PATH}
        strokeWidth="0.5"
        strokeLinejoin="round"
        className="fill-[#181512] stroke-[#181512] dark:fill-[#FFFFFF] dark:stroke-[#FFFFFF] transition-colors duration-300"
      />

      {animated && (
        <>
          <g mask={`url(#${maskId})`} className="pointer-events-none">
            <rect
              className="animate-logo-shimmer"
              x="0"
              y="-20"
              width="95"
              height="160"
              fill={`url(#${shimmerId})`}
            />
          </g>

          {/* Виразна ювелірна зірочка біля слова DECOR: загоряється в момент підходу блику і повільно згасає */}
          <g className="animate-logo-sparkle pointer-events-none" aria-hidden="true">
            <circle cx="327" cy="88" r="19" fill={`url(#${sparkleGlowId})`} />
            {/* Діагональні тонкі промені */}
            <path
              d="M319 80L335 96M335 80L319 96"
              strokeWidth="1.4"
              strokeLinecap="round"
              className="stroke-[#C88A14]/75 dark:stroke-[#FFDF85]/80"
            />
            {/* Головна 4-променева зірка */}
            <path
              d="M327 68C327 82.8 329.8 88 347 88C329.8 88 327 93.2 327 108C327 93.2 324.2 88 307 88C324.2 88 327 82.8 327 68Z"
              strokeWidth="1.1"
              strokeLinejoin="round"
              className="fill-[#C88A14] stroke-[#8C5E14] dark:fill-[#FFDF85] dark:stroke-[#FFF6D6]"
            />
            {/* Яскраве діамантове ядро */}
            <circle
              cx="327"
              cy="88"
              r="3.2"
              className="fill-[#FFFFFF]"
            />
          </g>
        </>
      )}
    </svg>
  )
}

/**
 * Головний адаптивний компонент бренду:
 * ялинка та напис збалансовані, в єдиному кольорі та стилі
 */
export function BrandLogo({
  variant = "full",
  animated = true,
  label = "Jingle Decor",
  withDivider = true,
  className = "",
  treeClassName = "h-[25px] sm:h-[26px] md:h-[27px] w-auto shrink-0",
  textClassName = "h-[30px] sm:h-[32px] md:h-[33px] w-auto shrink-0",
  ...props
}: BrandLogoProps) {
  if (variant === "icon") {
    return <BrandTreeIcon animated={animated} label={label} className={treeClassName} />
  }

  if (variant === "text") {
    return <BrandNameLogo animated={animated} label={label} className={textClassName} />
  }

  return (
    <div
      className={cn(
        "inline-flex items-center select-none",
        withDivider ? "gap-2 sm:gap-2.5 md:gap-3" : "gap-3.5 sm:gap-[18px] md:gap-5",
        className
      )}
      role="img"
      aria-label={label}
      {...props}
    >
      <BrandTreeIcon
        animated={animated}
        label=""
        className={treeClassName}
        aria-hidden="true"
      />
      {withDivider && (
        <span
          className="h-[18px] sm:h-[20px] w-px shrink-0 bg-gradient-to-b from-transparent via-[#7A4F08]/40 to-transparent dark:via-[#FFDF85]/45 transition-colors duration-300"
          aria-hidden="true"
        />
      )}
      <BrandNameLogo
        animated={animated}
        label=""
        className={textClassName}
        aria-hidden="true"
      />
    </div>
  )
}
